  return (
    <div>
      <Presentation nom="Rami" prenom="Ahmed" >
        <p>Ce ci est un children props</p>
      </Presentation>
      <Presentation nom="Kamali" prenom="Ali">
        <button>Quitter</button>
      </Presentation>
    </div>
  );
}
root.render(<App />);
